package com.nextrade.service; import org.springframework.data.redis.core.StringRedisTemplate; import java.time.*; public final class RedisRateLimitStore implements RateLimitStore {private final StringRedisTemplate redis;public RedisRateLimitStore(StringRedisTemplate redis){this.redis=redis;}public RateLimitDecision tryConsume(String key,int capacity,Duration window){String script="local c=redis.call('INCR',KEYS[1]); if c==1 then redis.call('PEXPIRE',KEYS[1],ARGV[1]); end; return c";Long count=redis.execute(org.springframework.data.redis.core.script.DefaultRedisScript.of(script,Long.class),java.util.List.of("nextrade:ratelimit:"+key),Long.toString(window.toMillis()));long n=count==null?capacity+1:count;if(n<=capacity)return RateLimitDecision.allow(capacity-n);return RateLimitDecision.deny(Instant.now().plus(window));}}
